#include <iostream>

struct vec3 {
    double x, y, z;
    vec3(double x = 0, double y = 0, double z = 0) : x(x), y(y), z(z) {}
    vec3 operator-(const vec3& other) const {
        return vec3(x - other.x, y - other.y, z - other.z);
    }
};

vec3 minimumImageDistance(const vec3& r1, const vec3& r2, double boxSize) {
    vec3 dr = r2 - r1;
    double halfBox = boxSize / 2.0;

    if (dr.x > halfBox) {
        dr.x -= boxSize;
    } else if (dr.x < -halfBox) {
        dr.x += boxSize;
    }

    if (dr.y > halfBox) {
        dr.y -= boxSize;
    } else if (dr.y < -halfBox) {
        dr.y += boxSize;
    }

    if (dr.z > halfBox) {
        dr.z -= boxSize;
    } else if (dr.z < -halfBox) {
        dr.z += boxSize;
    }

    return dr;
}

int main() {
    // Test case 1: No wrapping
    vec3 r1(0.0, 0.0, 0.0);
    vec3 r2(1.0, 1.0, 1.0);
    vec3 result = minimumImageDistance(r1, r2, 10.0);
    std::cout << "Test 1: " << result.x << ", " << result.y << ", " << result.z << std::endl;

    // Test case 2: Wrapping in x
    vec3 r3(9.0, 0.0, 0.0);
    vec3 r4(1.0, 0.0, 0.0);
    result = minimumImageDistance(r3, r4, 10.0);
    std::cout << "Test 2: " << result.x << ", " << result.y << ", " << result.z << std::endl;

    // Test case 3: Wrapping in all dimensions
    vec3 r5(9.0, 9.0, 9.0);
    vec3 r6(1.0, 1.0, 1.0);
    result = minimumImageDistance(r5, r6, 10.0);
    std::cout << "Test 3: " << result.x << ", " << result.y << ", " << result.z << std::endl;

    return 0;
}

